entries[111898] = { ["name"] = "Grimoire: Teufelswache", ["text"] = "1 Seelensplitter 40 Meter Reichweite\nSofort 2 min Abklingzeit\nBeschwört eine Teufelswache, die das Ziel 17 Sek. lang angreift und 125% mehr Schaden verursacht.\n\nDie Teufelswache betäubt und unterbricht ihr Ziel, sobald sie beschworen wurde." }
