entries[112922] = { ["name"] = "Abyssal beschwören", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört einen Meteor aus dem Wirbelnden Nether, der allen Gegnern im Zielgebiet (60% der Zaubermacht) Feuerschaden zufügt und sie für 25 Sek. betäubt. Aus dem Krater erhebt sich ein Abyssal, der 30 Sek. lang unter dem Befehl des Zaubernden steht.\n\nDer Abyssal verursacht schweren Flächenschaden und greift vorrangig Ziele in der Nähe des Einschlagsorts an." }
