entries[113959] = { ["name"] = "Schwere Rüstung", ["text"] = "Sofort\nDie schwere Rüstung, die von dieser Kreatur getragen wird, verringert allen erlittenen Schaden um 20%. Der Effekt bleibt bestehen, bis die Kreatur 967 Schaden erlitten hat." }
