entries[113966] = { ["name"] = "Dornen", ["text"] = "30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem, der es schlägt, Naturschaden zufügen. Hält 1 Min. lang an." }
entries[113967] = { ["name"] = "Federhaken", ["text"] = "10 Meter Reichweite\nWirken in 2 sek.\nSchleudert Dornen nach einem Gegner und verursacht so Naturschaden." }
entries[113968] = { ["name"] = "Pandarisches Teeservice", ["text"] = "Wirken in 2 sek. 3\nDie Pandaren verfügen über eine reichhaltige Teegeschichte. Seiner Vorbereitung wurde genau so viel Aufmerksamkeit geschenkt wie dem Geheimnis seiner fachgerechten Einnahme. Dieses einfache Teeservice stammt aus der Herrschaft der Mogu und gewährte seinem Besitzer in einer Zeit großer Schmerzen und Unterjochung Trost und Erholung. Obwohl es Sprünge hat und kaputt ist, dient es als Erinnerung daran, dass es die einfachen Dinge im Leben sind, die Trost spenden." }
entries[113969] = { ["name"] = "Ungerüstet", ["text"] = "100 Meter Reichweite\nSofort\nErhöht den erlittenen Schaden um 200%." }
entries[113970] = { ["name"] = "Ungerüstet", ["text"] = "100 Meter Reichweite\nSofort\nErhöht den erlittenen Schaden um 200%." }
entries[113971] = { ["name"] = "Pandarisches Brettspiel", ["text"] = "Wirken in 2 sek. 3\nPandaren lieben Spiele. Vor allem dieses Spiel ist seit der Zeit des ersten Pandarenherrschers eines ihrer Lieblingsspiele. Dies ist ein besonders edles Exemplar eines uralten Bretts." }
entries[113972] = { ["name"] = "Zwillingsbierkrüge des Brauvaters Quan Tou Kuo", ["text"] = "Wirken in 2 sek. 3\nEin Paar Zwillingsbierkrüge aus Ebenholz und Jade. Brauvater Quan Tou Kuo, 'der Beidhändige', wollte die Nebenwirkungen von hochprozentigen Getränken durch die Erschaffung der perfekten Dualität von Gebräuen mildern. Im korrekten Verhältnis getrunken vermischen sich das Hellbier des Geistes und das Starkbier des Verstandes im Magen des Trinkers und verursachen einen Zustand der Erleuchtung und des Wohlgefallens ohne den Verlust des Urteilsvermögens und der Selbstbeherrschung, die durch weniger ausgefeilte Gebräue so oft hervorgerufen werden. Unglücklicherweise sind die Geheimnisse des Brauvaters im Lauf der Zeit verloren gegangen; diese mit Liebe hergestellten Trinkkrüge dienen jedoch als ständige Erinnerung an sein Wissen." }
entries[113973] = { ["name"] = "Gehstock des Brauvaters Ren Yun", ["text"] = "Wirken in 2 sek. 3\nEiner von vielen Gehstöcken im Besitz des geheimnisvollen Brauvaters Ren Yun. Da er von Geburt an blind war, waren all seine anderen Sinne geschärft, weshalb er die Gebräue seiner Zeit als zu herb oder bitter empfand. Durch jahrelange Experimente entwickelte er vier perfekte Gebräue, die jedem seiner anderen Sinne zusprachen. Jedoch, das \"eine Gebräu\", das allen seinen vier Sinnen gleichzeitig eine Freude war, blieb ihm lange verwehrt. Erst am Ende seines langen Lebens gelang es ihm, sein Meisterwerk zu vollenden, sein \"Viersinnebräu\", das zur erstaunlichsten Entdeckung seiner Generation wurde. Leider ging dieses Rezept jedoch verloren, da Ren Yuns Handschrift absolut unleserlich war." }
entries[113974] = { ["name"] = "Leeres Fässchen des Brauvaters Xin Wo Yin", ["text"] = "Wirken in 2 sek. 3\nDer herzförmige Zapfhahn dieses Fasses deutet darauf hin, dass es sich um ein Artefakt des verstorbenen Brauvaters Xin Wo Yin, genannt 'der Untröstliche', handelt. Vor vielen Generationen erfand dieser gefeierte Brauvater 'Herzensfrohbräu', ein Gebräu, das seinen Trinker mit einem tiefen Gefühl der Wärme und des Wohlbefindens durchdringt. Angeblich war Xin Wo Yin so von dem Resultat seiner Braukunst angetan, dass er um jedes Fass, das seine Brauerei verließ, bittere Tränen vergoss, vermutlich also auch um dieses Fass. Dass es leer ist, stimmt Euch selbst ebenfalls etwas verdrießlich." }
entries[113975] = { ["name"] = "Verzierter Bronzespiegel", ["text"] = "Wirken in 2 sek. 3\nDas Glas selbst ist zwar schon lange verschwunden, doch die Rückseite dieses Spiegels ist eine kunstvoll gearbeitete Bronzescheibe mit einer Abbildung des Roten Kranichs der Hoffnung. Eine Widmung lautet: 'Für meine geliebte Lin / Meine Schöne, meine Taube / Dieses Bild der Perfektion / Dein Spiegelbild / Meine Liebe - Yao'" }
entries[113976] = { ["name"] = "Begräbnisfigurine aus Porzellan mit Goldintarsien", ["text"] = "Wirken in 2 sek. 3\nStatuetten wie diese, die anlässlich des Todes eines geliebten Wesens in Auftrag gegeben wurden, helfen den trauernden Hinterbliebenen dabei, mit ihrem Verlust zurechtzukommen. Diese Statuette ist das Abbild einer schönen jungen Lehrensucherin der Pandaren namens Lin. Laut Inschrift starb sie an einem schweren Fieber, das während der kurzen Regierungszeit des Ho-zen-Kaisers Rikktik durch das Tal der vier Winde fegte." }
entries[113977] = { ["name"] = "Medizindöschen", ["text"] = "Wirken in 2 sek. 3\nEin vollständiger Satz von Medizindöschen aus Messing, mit fein eingravierten Beschriftungen, die zur Aufbewahrung einer mannigfaltigen Auswahl an wirkungsstarken Heilkräutern dienten. Obwohl der genaue Zweck der meisten Kräuter wohl ein Rätsel bleiben wird, benennt eine kleine Tafel an der Kiste den Besitzer als Yao Pralltatze, einen Mediziner, dessen Name im Tal der Vier Winde aufgrund seines eindrucksvollen Schaffens noch immer mit Gesundheit und Wohlbefinden in Zusammenhang gebracht wird. Yao war nie verheiratet - die Legende besagt, dass sein Herz auf ewig gebrochen war." }
entries[113978] = { ["name"] = "Perle von Yu'lon", ["text"] = "Wirken in 2 sek. 3\nUm die Mitte dieser Jadekugel ist eine Schlange geätzt, die sich selbst in den Schwanz beißt. Auf den beiden Kugelhälften ist die folgende Inschrift zu lesen: 'Nur eins ist gewiss: Jedes Ende bedeutet auch einen neuen Anfang.' Diese Kugel, die aus dem Zeitalter des Pandarenkaisers Shu Blindauge stammt und zu Ehren der Jadeschlage hergestellt wurde, stellt ihre Wiedergeburt in einem neuen Körper alle hundert Jahre dar. In ihrem Tempel im Jadewald spendet Yu'lon bis zum heutigen Tag Weisheit und Erkenntnis." }
entries[113979] = { ["name"] = "Standarte von Niuzao", ["text"] = "Wirken in 2 sek. 3\nEin aufgerolltes dickes Segeltuch, das sich, wenn emporgehalten, als das stolze Emblem des Pandarenreiches entfaltet. Schwere eiserne Ringe hängen an langen ledernen Bändern, die an der unteren Seite befestigt sind und das Banner straffen. Jeder Lederstreifen ist mit einer Mahnung an den Standartenträger bestickt: 'Angst trachtet danach, Euch zu schwächen. / Erlaubt ihr stattdessen, Euch zu enthüllen.'" }
entries[113980] = { ["name"] = "Schirm von Chi-Ji", ["text"] = "Wirken in 2 sek. 3\nDas zarte Papierdach dieses großen Bambusschirms ist auf wundersame Weise seit seiner Herstellung irgendwann während der langen Donnerpfotendynastie erhalten geblieben. Auf seiner Unterseite ist eine Decke pechschwarzer Sturmwolken abgebildet, während auf der Oberseite eine prächtige, purpurfarbene Sonne erstrahlt. Über den Wolken steht in eleganter Schönschrift eine kurze Botschaft zu lesen: 'Hoffnung ist die Sonne hinter einem sturmverhangenen Himmel. Sie lebt ständig im Herzen, bleibt jedoch dem Auge verborgen.' Chi-Ji, der Rote Kranich, dient den Pandaren seit Jahrhunderten als Symbol der Hoffnung. Sein kunstvoller und prächtiger Tempel steht in einem wilden Dschungel im Süden des Tals der Vier Winde.\nSchirm von Chi-Ji\nWird an Kriegsmeute gebunden\nIn Schildhand geführt\n+6 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n32\n\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter 'Restaurierte Artefakte' protokolliert.\"" }
entries[113981] = { ["name"] = "Speer von Xuen", ["text"] = "Wirken in 2 sek. 3\nDieser eindrucksvolle Speer, der während der Zandalari-Trollkriege gefertigt wurde, ist überraschend leicht und biegsam. Sein lackierter Holzschaft ist von tiefen Narben übersät, die Spitze scheint jedoch völlig unversehrt zu sein. Angesichts der Länge dieser Waffe und ihres Ursprungsalters geht Ihr davon aus, dass sie für die Verwendung vom Rücken einer Flugschlange aus gedacht war. In den verwitterten Griff ist eine Mitteilung geritzt: 'Euer einziger Gegner seid Ihr selbst.' Xuen der Weiße Tiger ist für seine Wildheit und sein Können im Kampf berüchtigt. In seinem Tempel, hoch oben im Kun-Lai-Gebirge, stählen angehende Krieger ihre Stärke durch Disziplin.\nSpeer von Xuen\nWird an Kriegsmeute gebunden\nZweihändig Stangenwaffe\n7 - 15 Schaden Geschwindigkeit 3.60\n(3.1 Schaden pro Sekunde)\n+4 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 100 / 100\n32\n\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter 'Restaurierte Artefakte' protokolliert.\"" }
entries[113982] = { ["name"] = "Fesseln der Rebellion", ["text"] = "Wirken in 2 sek. 3\nDiese aus Eisen geschmiedeten und von Unterwerfungs- und Schmerzzaubern durchdrungenen Fesseln mit ihren nach innen gerichteten Stacheln wurden den von den Mogu versklavten Völkern aufgezwungen. Obwohl die Zauber schon vor langer Zeit abgeklungen sind, jagt Euch ihre Grausamkeit noch immer Schauer über den Rücken." }
entries[113983] = { ["name"] = "Gesprungener Runenstein der Mogu", ["text"] = "Wirken in 2 sek. 3\nIm Gegensatz zu 'niederen Völkern', die in den magischen Künsten ausgebildet werden müssen, war diese Fähigkeit den Mogu angeboren. Was über die Verwendung von Magie durch die Mogu bekannt ist, deutet eindeutig darauf hin, dass ihre Magieanwender sich in keine bekannten Kategorien wie Magier oder Hexenmeister einordnen ließen. Besondere Bedeutung wurde der Magie zur Formung von Fleisch und zur Erfassung von Geistern verliehen. Die eigenartigen Rückstände der Magie, mit der dieser Stein durchdrungen war, sind für die modernen Völker von Azeroth nur schwer zu verstehen. Sonderbarerweise ähneln einige der Zeichen um die Rune der Sprache der Titanen." }
entries[113984] = { ["name"] = "Arm aus Terrakotta", ["text"] = "Wirken in 2 sek. 3\nNachdem die Mogu ihre Möglichkeiten an sterblichen Kriegersklaven ausgeschöpft hatten, richteten sie ihr Augenmerk auf die Erschaffung von Armeen aus animierten Konstrukten, die für sie kämpfen sollten. Da diese Terrakottakrieger manchmal jahrhundertelang inaktiv waren, lässt sich nur schwer feststellen, wo genau dieser hier hergestellt oder eingesetzt wurde. Der Abrieb an der Unterseite des abgetrennten Arms deutet allerdings darauf hin, dass er im Kampf niedergestreckt wurde." }
entries[113985] = { ["name"] = "Versteinerte Peitsche aus Knochen", ["text"] = "Wirken in 2 sek. 3\nDiese Peitsche wurde aus dem Rückgrat einer großen, vorzeitlichen Kreatur gefertigt. Mit ihr wurde das Blut vieler Sklaven vergossen." }
entries[113986] = { ["name"] = "Insigne des Donnerkönigs", ["text"] = "Wirken in 2 sek. 3\nDieses Jadeemblem wird von einer Krone und gekreuzten Blitzen geziert. Es handelt sich um ein Abzeichen, das einst von Soldaten des ersten Moguherrschers Lei Shen getragen wurde." }
entries[113987] = { ["name"] = "Edikte des Donnerkönigs", ["text"] = "Wirken in 2 sek. 3\nDieser Gesetzeskodex, in der einheitlichen Sprache des ersten Reiches verfasst, wurde sorgfältig in die Steintafel gemeißelt. Angeführt wird die Liste von dem Erlass, dass Verhetzung, Aufruhr und Rebellion mit der öffentlichen Ausweidung bestraft werden." }
entries[113988] = { ["name"] = "Eisenamulett", ["text"] = "Wirken in 2 sek. 3\nDieses riesige eiserne Amulett wiegt mehr als eine Streitaxt. Die Krieger der Mogu trugen häufig 'Schmuck' wie diesen, um ihre Stärke zu demonstrieren." }
entries[113989] = { ["name"] = "Brandeisen eines Kriegsherren", ["text"] = "Wirken in 2 sek. 3\nDieses Brandeisen mit dem Symbol eines unbedeutenden Kriegsherren der Mogu wurde nicht zum Markieren von Vieh, sondern von humanoiden Sklaven benutzt." }
entries[113990] = { ["name"] = "Mogumünze", ["text"] = "Wirken in 2 sek. 3\nDiese Währung wurde zu Regierungszeiten des Moguherrschers Wai benutzt, der in all seiner zähnefletschenden Pracht dargestellt ist. Auf der Rückseite der Münze ist der Wechsel der Mogudynastien abgebildet, ein blutiger Vorgang, bei dem der vorhergehende Herrscher gestürzt und hingerichtet werden muss. In vielerlei Hinsicht waren die antiken Regierungen der Mogu Meritokratien, die auf brutaler Stärke und schrecklicher Durchtriebenheit basierten." }
entries[113991] = { ["name"] = "Verschlissenes Kassenbuch eines Architekten", ["text"] = "Wirken in 2 sek. 3\nTrotz der mächtigen Magie, über die sie verfügen, bevorzugen die Mogu zur Errichtung gewaltiger Denkmäler häufig den Einsatz von Sklaven. Dieses Kassenbuch dokumentiert den Sklavenverschleiß bei der Errichtung eines solchen Denkmals." }
entries[113992] = { ["name"] = "Qilenstatuette", ["text"] = "Wirken in 2 sek. 3\nDiese Statuette, die während der kurzen Herrschaft des Mogukaisers Kang erschaffen wurde, war Teil eines Experiments, bei dem Qilen-Diener in kleine Steine gebunden wurden. Das Experiment wurde abgeblasen, da die Kraft der auf diese Weise gebundenen Qilen sich so sehr verringerte, dass sie als wertlos betrachtet wurden.\nQilenstatuette\nWird an Kriegsmeute gebunden\nEinzigartig anlegbarSchmuck\nErhöht Eure Meisterschaftswertung um + 6.\nBenutzen: Beschwört den artefaktgebundenen Qilen. (10 Min Abklingzeit)\n32\n\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter 'Restaurierte Artefakte' protokolliert.\"" }
entries[113993] = { ["name"] = "Anatomische Puppe", ["text"] = "Wirken in 2 sek. 3\nEine anatomisch genaue Pandarenpuppe. Sie wurde genutzt, um Foltermechaniken zu dokumentieren.\nAnatomische Puppe\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört 5 Min. lang eine anatomische Puppe am Zielort, die als Zielattrappe dient.\n\nKann nur im Freien von Pandaria eingesetzt werden. (1 Stunde Abklingzeit)\n\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter 'Restaurierte Artefakte' protokolliert.\"" }
