entries[113998] = { ["name"] = "Geheul der Verzweiflung", ["text"] = "Kanalisiert (Wirken in 10 sek.)\nRuft niedere Sha herbei. Beschwört 10 Sek. lang alle 2 Sek. eins." }
entries[113999] = { ["name"] = "Knochenstachel", ["text"] = "100 Meter Reichweite\nWirken in 1 sek.\nSchlägt mit einem Knochenstachel nach dem Ziel und fügt ihm 4739 körperlichen Schaden zu." }
