entries[114004] = { ["name"] = "Durchstechender Wurf", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 2 sek.)\nHundemeister Braun wirft eins seiner Messer auf einen beliebigen Gegner, fügt dadurch allen in der Flugbahn befindlichen Gegnern 1658 körperlichen Schaden zu und wirkt auf die Ziele 'Blutige Sauerei'." }
entries[114006] = { ["name"] = "Dröhnendes Gebrüll", ["text"] = "Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nVerringert 10 Sek. lang die Rüstung von Gegnern in der Nähe." }
entries[114007] = { ["name"] = "Seelenflamme", ["text"] = "Sofort\nErschafft einen Teich aus ätzenden Tränen, der Naturschaden verursacht und mit der Zeit wächst." }
entries[114009] = { ["name"] = "Seelenflamme", ["text"] = "Sofort\nEine leuchtende Seelenflamme fügt nahen Gegnern 41 Feuerschaden zu. Die Flamme wächst mit der Zeit." }
entries[114011] = { ["name"] = "Rüstungshieb", ["text"] = "Nahkampfreichweite\nSofort\nDer Hieb verursacht 150% Waffenschaden und erhöht den erlittenen körperlichen Schaden 10 Sek. lang um 20%. Stapelbar." }
entries[114014] = { ["name"] = "Shurikenwurf", ["text"] = "40 Energie 30 Meter Reichweite\nSofort\nWirft einen Shuriken auf ein gegnerisches Ziel, der [(23.7838% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] körperlichen Schaden verursacht.\n\nGewährt 1 Combopunkt." }
entries[114015] = { ["name"] = "Erwartung", ["text"] = "Ihr könnt über bis zu 10 Combopunkte verfügen. Finishing-Moves zehren trotzdem maximal 5 Combopunkte auf." }
entries[114016] = { ["name"] = "Auf die Hörner nehmen", ["text"] = "8 - 30 Meter Reichweite\nWirken in 1 sek. 5 sek. Abklingzeit\nBei diesem Vorstoß auf den aktuellen Standort des Gegners wird die Bewegungsgeschwindigkeit 3 Sek. lang um 60% erhöht. Bei Ankunft am Ziel werden alle Gegner in der Nähe zurückgestoßen." }
entries[114017] = { ["name"] = "Durchstechender Wurf" }
entries[114018] = { ["name"] = "Verhüllender Nebel", ["text"] = "Sofort 6 min Abklingzeit\nBenötigt Verstohlenheit\nBreitet einen Schleier aus, der Gruppen- und Schlachtzugsmitglieder innerhalb von 30 Metern in Schatten hüllt und 15 Sek. lang tarnt." }
