entries[114049] = { ["name"] = "Aszendenz", ["text"] = "2.5% von Grundmana\nSofort 3 min Abklingzeit\nDer Schamane verwandelt sich für 15 Sek. in ein Wesen aus reiner Elementarenergie.\n\nElementar:\nIn Gestalt des Flammenaszendenten hat 'Lavaeruption' keine Abklingzeit und 'Kettenblitzschlag' wird verstärkt und zu einem 'Lavastrahl' umgewandelt.\n\nVerstärkung:\nIn Gestalt des Luftaszendenten werden automatische Angriffe und 'Sturmschlag' zu Windangriffen, die Rüstung ignorieren und eine Reichweite von 30 Metern haben.\n\nWiederherstellung:\nIn Gestalt des Wasseraszendenten wird alle hervorgerufene Heilung dupliziert und gleichmäßig auf alle Verbündeten in der Nähe aufgeteilt." }
entries[114050] = { ["name"] = "Aszendenz", ["text"] = "40 Meter Reichweite\nSofort 3 min Abklingzeit\nIhr verwandelt Euch für 15 Sek. in einen Flammenaszendenten und setzt sofort 'Flammenschock' und mit 100% Effektivität 'Lavaeruption' gegen bis zu 6 Gegner in der Nähe ein.\n\nIn diesem Zustand ist der Schaden von 'Elementarüberladung' um 150% erhöht und Zauber, die von 'Meisterschaft: Elementarüberladung' betroffen sind, verursachen 1 weiteres Mal 'Elementarüberladung'." }
entries[114051] = { ["name"] = "Aszendenz", ["text"] = "Sofort 3 min Abklingzeit\nVerwandelt Euch für 15 Sek. in einen Luftaszendenten und fügt sofort allen Gegnern innerhalb von 8 Metern (215.625% der Angriffskraft) Naturschaden zu. In dieser Gestalt sind Kosten und Abklingzeit von 'Sturmschlag' um 60% verringert und Eure automatischen Angriffe sowie 'Sturmschlag' werden zu Windangriffen, die Rüstung umgehen und eine Reichweite von 30 Metern haben. [ Statikzuwachs : Während 'Aszendenz' aktiv ist, erzeugt Ihr alle 1 Sek. 0 Stapel von 'Waffe des Mahlstroms' ]" }
entries[114052] = { ["name"] = "Aszendenz", ["text"] = "Sofort 3 min Abklingzeit\nIhr verwandelt Euch für 15 Sek. in einen Wasseraszendenten, dupliziert dabei Eure hervorgerufene Heilung mit 70% Effektivität und heilt sofort (876% der Zaubermacht) Gesundheit. Sämtliche von Euch hervorgerufene Heilung wird gleichmäßig auf Verbündete innerhalb von 40 Metern verteilt." }
